#include <iostream>
#include <memory>

struct C {
    C(int i) : i(i) {}
    C(int i, float f) : i(i), f(f) {}
    int i;
    float f{};
};

int main() {
    // Single object construction
    auto sp1 = std::make_shared<C>(1);
    std::cout << "sp1->{ i:" << sp1->i << ", f:" << sp1->f << " }\n";

    // Multiple arguments
    std::shared_ptr<C> sp2 = std::make_shared<C>(2, 3.0f);
    std::cout << "sp2->{ i:" << sp2->i << ", f:" << sp2->f << " }\n";

    return 0;
}

// Single allocation benefit:
// std::shared_ptr<T>(new T(...)) performs TWO allocations:
// 1. One for the object T
// 2. One for the control block
//
// std::make_shared<T>(...) performs ONE allocation:
// - Combined allocation for object + control block

// Exception-safe usage:
// Dangerous: potential leak if function() throws
// processWidget(std::shared_ptr<Widget>(new Widget), function());

// Safe: make_shared guarantees no leak
// processWidget(std::make_shared<Widget>(), function());
